) VALUES (
    'STA-06',
    'Cross-Browser Compatibility Testing System',
    'Software Testing and Automation',
    'Develop an automation system to test website functionality and responsive layout across multiple browsers and screen viewports.',
    'Web applications frequently suffer from browser-specific rendering bugs, CSS layout breakage, and broken hyperlinks across Chromium, Firefox, and WebKit on mobile vs desktop screens.',
    '["Develop an automated cross-browser test suite using Microsoft Playwright","Execute tests across multiple browser rendering engines: Chromium, Firefox, and WebKit (Safari)","Validate responsive viewports covering Mobile (375px), Tablet (768px), and Desktop (1440px)","Implement automated full-page screenshot comparison, broken link detection, and compatibility reporting"]'::jsonb,
    '[]'::jsonb,
    '["Automated cross-browser execution across Chromium (Chrome/Edge), Firefox, and WebKit (Safari)","Multi-viewport responsive testing: Mobile (375x667), Tablet (768x1024), and Desktop (1440x900)","Responsive layout checks: verifying hamburger menu toggles on mobile and full navbar on desktop","Full-page screenshot capture across all browser and resolution permutations","Visual comparison detecting layout shifts between baseline and candidate renders","Automated broken-link crawler checking all page anchor tags for HTTP 404/500 errors","Consolidated cross-browser compatibility matrix report displaying pass/fail status per browser"]'::jsonb,
    '["Playwright","Python / JavaScript","Pytest","Pillow (for image diffing)"]'::jsonb,
    'Intermediate',
    4,
    '["Complete Playwright cross-browser automation repository with setup instructions","Full-page screenshot gallery across 3 browsers and 3 screen viewports","Broken-link crawler report cataloging all audited URLs and response codes","Consolidated Cross-Browser Compatibility Matrix Report and demonstration video"]'::jsonb,
    '["Cross-browser coverage across Chromium, Firefox, and WebKit (30%)","Responsive viewport testing and visual screenshot comparison (25%)","Broken-link crawler implementation and reporting accuracy (25%)","Code quality, documentation, and demonstration video (20%)"]'::jsonb,
    '["https://playwright.dev/docs/intro","https://docs.pytest.org/en/stable/","https://docs.python.org/3/"]'::jsonb,
    true,
    '["Cross-browser test automation using Microsoft Playwright (Python or JavaScript)","Multi-viewport responsive testing and CSS layout validation","Automated visual regression testing and screenshot comparison techniques","Automated broken-link crawling and HTTP status verification"]'::jsonb,
    '["Python or JavaScript/TypeScript programming","Understanding of web rendering engines (Chromium, Gecko/Firefox, WebKit)","Basic knowledge of responsive web design (CSS media queries, viewport sizes)"]'::jsonb,
    '["Python 3.9+ OR Node.js 18+","Microsoft Playwright (`playwright install` for Chromium, Firefox, WebKit)","Pytest (if Python) or Playwright Test Runner (if JS)","Target website: local web app or responsive demo portal"]'::jsonb,
    '["Framework must execute identical functional assertions across all 3 browser engines","Broken-link crawler must test all internal links on the site and report any non-200 HTTP statuses","Visual layout checks must verify that primary navigation elements are visible and clickable across viewports","System must generate consolidated HTML compatibility report matrix"]'::jsonb,
    '["Parallel test execution across browsers to optimize total execution time","Headless and headed execution modes toggleable via command-line flags","Resilient locators using Playwright''s user-facing locators (role, text, label)"]'::jsonb,
    '[{"milestone":1,"title":"Milestone 1 — Compatibility Test Plan & Playwright Setup","description":"Analyze cross-browser requirements, define browser/viewport matrix, and initialize Playwright project.","tasks":["Formulate Cross-Browser Test Plan defining target browsers (Chromium, Firefox, WebKit) and viewports","Identify critical user paths and responsive breakpoints to be audited","Set up Playwright environment (`pip install pytest-playwright` and `playwright install`)","Initialize Git repository with configuration and directory structure"],"deliverables":"Cross-Browser Test Plan matrix, Playwright environment setup, and GitHub repository."},{"milestone":2,"title":"Milestone 2 — Cross-Browser & Multi-Viewport Automation","description":"Implement automated test scripts running across Chromium, Firefox, and WebKit on mobile/desktop viewports.","tasks":["Implement Playwright test fixtures configuring browser engines (Chromium, Firefox, WebKit)","Configure viewport emulation for Mobile (375x667), Tablet (768x1024), and Desktop (1440x900)","Write functional assertions verifying responsive behavior (e.g. mobile drawer menu vs desktop nav)","Execute parallel cross-browser test runs and verify cross-engine consistency"],"deliverables":"Cross-browser test suites, multi-viewport runner scripts, and initial test execution logs."},{"milestone":3,"title":"Milestone 3 — Visual Comparison & Broken-Link Crawler","description":"Implement full-page screenshot capture, visual layout comparisons, and automated broken-link crawler.","tasks":["Implement automated full-page screenshot capture across all 9 browser/viewport permutations","Implement visual comparison logic detecting layout deviations or element overlaps","Develop automated broken-link crawler extracting all anchor tags and verifying HTTP response codes","Log broken links with source page URL and HTTP status code"],"deliverables":"Automated screenshot gallery, visual comparison module, and broken-link crawler report."},{"milestone":4,"title":"Milestone 4 — Consolidated Matrix Report, Documentation & Demo","description":"Generate consolidated cross-browser compatibility matrix report, write documentation, and record demo video.","tasks":["Compile consolidated Cross-Browser Compatibility Matrix Report summarizing pass/fail status per browser","Document identified browser-specific quirks and layout recommendations","Write clear project setup documentation detailing Playwright execution commands","Record demonstration video showing parallel browser test execution and matrix report review"],"deliverables":"Final GitHub repository, Compatibility Matrix HTML report, and video walkthrough."}]'::jsonb,
